def op(n):
    d = n % 10
    return (n // 10) + 3 * d

def check_all():
    for n in range(1, 271):
        path = [n]
        seen = {n: 0}
        for i in range(1, 1000):
            n = op(n)
            path.append(n)
            if n in seen:
                # Cycle found
                print(f"n={path[seen[n]]} leads to cycle: {path[seen[n]:]}")
                break
            seen[n] = i
            if n > 10000: break

check_all()
